/**
 * public/js/teambuilder-engine.js
 * Alpine.js component for the Nuzlox teambuilder page.
 *
 * Validation data is loaded from /cache/ruleset-validator.json (generated by
 * scripts/generate-ruleset-cache.js and refreshed on every ruleset publish).
 *
 * @ref wallbreaker/docs/accessibility/APXpatterns/challenge-patterns.md — Safe Practice Zone
 * @ref wallbreaker/docs/accessibility/WCAG/04-robust.md §4.1.3 (live region for validation)
 */

'use strict';

/* ─── Pokémon data (bundled minimal set for demo; real app fetches from PokéAPI cache) ─── */
const POKEMON_ROSTER = [
  // Gen 1 — kosher candidates visible in picker; forbidden ones still appear so user sees reason
  { id: 1,   name: 'Bulbasaur',  types: ['grass','poison'], category: 'land' },
  { id: 4,   name: 'Charmander', types: ['fire'],           category: 'land' },
  { id: 7,   name: 'Squirtle',   types: ['water'],          category: 'sea'  },
  { id: 25,  name: 'Pikachu',    types: ['electric'],       category: 'land' },
  { id: 39,  name: 'Jigglypuff', types: ['normal','fairy'], category: 'land' },
  { id: 50,  name: 'Diglett',    types: ['ground'],         category: 'land' },
  { id: 54,  name: 'Psyduck',    types: ['water'],          category: 'sea'  },
  { id: 63,  name: 'Abra',       types: ['psychic'],        category: 'land' },
  { id: 92,  name: 'Gastly',     types: ['ghost','poison'], category: 'forbidden' },
  { id: 94,  name: 'Gengar',     types: ['ghost','poison'], category: 'forbidden' },
  { id: 109, name: 'Koffing',    types: ['poison'],         category: 'land' },
  { id: 113, name: 'Chansey',    types: ['normal'],         category: 'land' },
  { id: 116, name: 'Horsea',     types: ['water'],          category: 'sea'  },
  { id: 129, name: 'Magikarp',   types: ['water'],          category: 'sea'  },
  { id: 130, name: 'Gyarados',   types: ['water','flying'], category: 'sky'  },
  { id: 131, name: 'Lapras',     types: ['water','ice'],    category: 'sea'  },
  { id: 132, name: 'Ditto',      types: ['normal'],         category: 'land' },
  { id: 133, name: 'Eevee',      types: ['normal'],         category: 'land' },
  { id: 143, name: 'Snorlax',    types: ['normal'],         category: 'land' },
  { id: 147, name: 'Dratini',    types: ['dragon'],         category: 'land' },
  { id: 197, name: 'Umbreon',    types: ['dark'],           category: 'forbidden' },
  { id: 248, name: 'Tyranitar',  types: ['rock','dark'],    category: 'forbidden' },
  { id: 778, name: 'Mimikyu',    types: ['ghost','fairy'],  category: 'forbidden' },
  { id: 932, name: 'Nacli',      types: ['rock'],           category: 'land' },
  { id: 933, name: 'Naclstack',  types: ['rock'],           category: 'land' },
  { id: 934, name: 'Garganacl',  types: ['rock'],           category: 'land' },
];

/* ─── Alpine.js component ──────────────────────────────────────────────────── */
function teambuilder(playthroughId) {
  return {
    /* state */
    schema: null,
    roster: POKEMON_ROSTER,
    slots: Array(6).fill(null),  // each: { id, name, types[], category, nickname, moves[], item }
    activeSlot: null,            // index of selected slot (0-5)
    pickerOpen: false,
    pickerQuery: '',
    validation: { valid: null, violations: [], warnings: [] },
    savedTeamId: null,
    teamName: '',
    saving: false,
    saveError: null,
    playthroughId,

    /* ── lifecycle ── */
    async init() {
      try {
        const res = await fetch('/cache/ruleset-validator.json');
        if (res.ok) this.schema = await res.json();
      } catch (e) {
        console.warn('Could not load ruleset validator:', e);
      }
    },

    /* ── slot management ── */
    selectSlot(index) {
      this.activeSlot = index;
      this.pickerOpen = true;
      this.pickerQuery = '';
    },

    clearSlot(index) {
      this.slots[index] = null;
      if (this.activeSlot === index) this.pickerOpen = false;
      this._validate();
    },

    pickMon(mon) {
      if (this.isForbidden(mon)) return;
      if (this.activeSlot === null) return;
      this.slots[this.activeSlot] = {
        ...mon,
        nickname: '',
        moves: [],
        item: null,
        bred: false,
      };
      this.pickerOpen = false;
      this.activeSlot = null;
      this._validate();
    },

    /* ── picker helpers ── */
    get filteredRoster() {
      const q = this.pickerQuery.toLowerCase();
      return this.roster.filter(m => m.name.toLowerCase().includes(q));
    },

    isForbidden(mon) {
      if (!this.schema) return false;
      const { forbidden_types = [], forbidden_species_categories = [] } = this.schema;
      if (forbidden_species_categories.includes(mon.category)) return true;
      return mon.types.some(t => forbidden_types.includes(t));
    },

    /* ── validation ── */
    _validate() {
      const team = this.slots.filter(Boolean);
      if (!team.length) { this.validation = { valid: null, violations: [], warnings: [] }; return; }
      if (!this.schema) { this.validation = { valid: null, violations: [{ msg: 'Ruleset not loaded' }], warnings: [] }; return; }

      const violations = [];
      const warnings   = [];

      const {
        forbidden_types = [],
        restricted_types = [],
        forbidden_species_categories = [],
        forbidden_moves = [],
        forbidden_move_categories = [],
        forbidden_items = [],
      } = this.schema;

      for (const mon of team) {
        /* Forbidden types */
        const forbiddenTypeHit = mon.types.filter(t => forbidden_types.includes(t));
        if (forbiddenTypeHit.length) {
          violations.push({ msg: `${mon.name}: forbidden type(s) — ${forbiddenTypeHit.join(', ')}` });
        }

        /* Forbidden species categories */
        if (forbidden_species_categories.includes(mon.category)) {
          violations.push({ msg: `${mon.name}: forbidden species category (${mon.category})` });
        }

        /* Restricted types — warn but don't block */
        const restrictedHit = mon.types.filter(t => restricted_types.some(r => r.type === t));
        if (restrictedHit.length) {
          warnings.push({ msg: `${mon.name}: restricted type (${restrictedHit.join(', ')}) — verify move compliance` });
        }

        /* Forbidden moves */
        for (const move of (mon.moves || [])) {
          if (forbidden_moves.includes(move)) {
            violations.push({ msg: `${mon.name}: forbidden move — ${move}` });
          }
          if (forbidden_move_categories.includes(move)) {
            warnings.push({ msg: `${mon.name}: move category restricted — ${move}` });
          }
        }

        /* Forbidden item */
        if (mon.item && forbidden_items.includes(mon.item)) {
          violations.push({ msg: `${mon.name}: forbidden item — ${mon.item}` });
        }
      }

      /* Breeding requirement — at least one mon must have bred=true if team has ≥2 */
      if (team.length >= 2 && !team.some(m => m.bred)) {
        warnings.push({ msg: 'At least one Pokémon should be bred (requirement for team play)' });
      }

      this.validation = { valid: violations.length === 0, violations, warnings };
    },

    /* ── save team ── */
    async saveTeam() {
      const team = this.slots.filter(Boolean);
      if (!team.length) return;
      this.saving = true;
      this.saveError = null;
      try {
        const csrf = document.querySelector('meta[name="csrf-token"]')?.content
                  || window.__JOURNAL_CSRF__
                  || '';
        const res = await fetch('/api/v1/teams', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
          body: JSON.stringify({
            name: this.teamName || 'My Team',
            playthrough_id: this.playthroughId || null,
            members: team.map((m, i) => ({
              slot: i,
              species: m.name,
              nickname: m.nickname || null,
              moves: m.moves || [],
              item: m.item || null,
              bred: m.bred || false,
            })),
          }),
        });
        const data = await res.json();
        if (!res.ok) throw new Error(data.error || 'Save failed');
        this.savedTeamId = data.id;
      } catch (err) {
        this.saveError = err.message;
      } finally {
        this.saving = false;
      }
    },
  };
}
